/* Danger — error, destructive action. Hue ~25.
   [data-invalid] applies the danger palette automatically: Base UI's Field
   emits data-invalid on Field.Root, and because palette roles are inherited
   via custom properties, the whole subtree (row, body, addon, control)
   becomes danger with no extra class.
   Do NOT use `aria-invalid:palette-danger` — Tailwind variants only apply to
   utilities, and palette-* is a plain CSS class: that syntax compiles
   nothing. Both themes declare all six roles. */

:root[data-theme="light"] :is(.palette-danger, [data-invalid]) {
    --palette-base: oklch(0.55 0.2 25);
    --palette-soft: oklch(0.94 0.07 25);
    --palette-line: oklch(0.85 0.1 25);
    --palette-contrast: oklch(1 0 0);
    --palette-accent: oklch(0.45 0.18 25);
    --palette-ring: var(--palette-accent);
}

:root[data-theme="dark"] :is(.palette-danger, [data-invalid]) {
    --palette-base: oklch(0.68 0.18 25);
    --palette-soft: oklch(0.3 0.08 25);
    --palette-line: oklch(0.4 0.1 25);
    --palette-contrast: oklch(0.12 0.02 25);
    --palette-accent: oklch(0.75 0.16 25);
    --palette-ring: var(--palette-accent);
}
